<?php namespace Workspace; ?>
<div class="overviewhead"><p class="lede">Кассовая книга по проектам и валютам.</p><a class="button secondary" href="<?= h(url('export',$filters)) ?>">Скачать CSV</a></div>
<form method="get" class="filters"><input type="hidden" name="p" value="finance"><label>Проект<select name="project"><option value="">Все проекты</option><?php selectOptions($projects,$selected) ?></select></label><label>С даты<input type="date" name="from" value="<?= h($filters['from'] ?? '') ?>"></label><label>По дату<input type="date" name="to" value="<?= h($filters['to'] ?? '') ?>"></label><button class="secondary">Применить</button></form>
<?php if ($balances): ?><div class="currencies"><?php foreach ($balances as $b): ?><div class="currency"><span>Движение за период · <?= h($b['currency']) ?></span><strong><?= h(money($b['income']-$b['expense'])) ?></strong><small>Поступило <?= h(money($b['income'])) ?> · Расход <?= h(money($b['expense'])) ?></small></div><?php endforeach ?></div><?php endif ?>
<?php if ($projects): ?><details class="editor" <?= !$rows?'open':'' ?>><summary>Провести операцию</summary><form method="post" class="formgrid"><?php formFields('cash.post') ?>
<label>Проект<select name="project_id" required><?php selectOptions($projects,$selected) ?></select></label><label>Тип операции<select name="direction"><?php selectOptions(DIRECTIONS) ?></select></label>
<label>Сумма<input name="amount" inputmode="decimal" required placeholder="0,00"></label><label>Валюта<select name="currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES)) ?></select></label>
<label>Дата операции<input type="date" name="booked_on" required value="<?= gmdate('Y-m-d') ?>" max="<?= gmdate('Y-m-d') ?>"></label><label>Назначение<input name="memo" maxlength="200" required></label><div class="formend"><button class="primary">Провести операцию</button></div></form></details>
<?php else: ?><p class="notice">Для денежной операции нужен проект. Его может создать владелец или менеджер.</p><?php endif ?>
<section class="panel"><div class="panelhead"><h2>Операции за период</h2></div><?php if (!$rows): ?><p class="empty">По выбранным условиям операций нет.</p><?php else: ?><div class="tablewrap"><table><thead><tr><th>Дата</th><th>Назначение / проект</th><th>Операция</th><th class="num">Сумма</th><th>Коррекция</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td class="nowrap"><?= h(displayDate($r['booked_on'])) ?></td><td><b><?= h($r['memo']) ?></b><small><?= h($r['project_title']) ?> · #<?= (int)$r['id'] ?></small></td><td><?= h(DIRECTIONS[$r['direction']]) ?></td><td class="num nowrap"><?= h(money((int)$r['amount_minor']).' '.$r['currency']) ?></td><td>
<?php if ($r['reversal_of']): ?>К #<?= (int)$r['reversal_of'] ?><?php elseif ($r['reversed_by']): ?>Сторно #<?= (int)$r['reversed_by'] ?><?php else: ?><details class="minor"><summary>Сторно</summary><form method="post"><?php formFields('cash.reverse') ?><input type="hidden" name="entry_id" value="<?= (int)$r['id'] ?>"><button class="secondary compact">Подтвердить сторно</button></form></details><?php endif ?></td></tr><?php endforeach ?></tbody></table></div>
<div class="pager"><?php if ($pageNo>1): ?><a href="<?= h(url('finance',$filters+['n'=>$pageNo-1])) ?>">Предыдущая</a><?php endif; if ($more): ?><a href="<?= h(url('finance',$filters+['n'=>$pageNo+1])) ?>">Следующая</a><?php endif ?></div><?php endif ?></section>
